CREATE OR REPLACE FUNCTION mission_creation_owner.human_assert(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.master_v2_sessions;l public.locations;us uuid[];
begin
IF mission_factory_owner.c395_human_mode_v1(p_session) THEN
PERFORM mission_factory_owner.c395_active_human_assert_v1(p_session);RETURN;END IF;
select * into strict m from public.master_v2_sessions where id=p_session;
if auth.uid() is null or m.master_user is distinct from auth.uid() or not public.master_v2_is_master(auth.uid())
or not mission_creation_owner.is_human(p_session) or m.closed_at is not null or m.suspended_at is not null
or m.stato not in('preparazione','in_corso','chiusura') then raise exception 'MC_HUMAN_AUTHORITY' using errcode='42501';end if;
select * into strict l from public.locations where id=m.location_id;
select array_agg(p.user_id_snapshot order by p.character_id) into us from public.master_v2_participants p
join public.characters c on c.id=p.character_id and c.user_id=p.user_id_snapshot
where p.session_id=p_session and p.left_at is null and p.engagement_state='attivo';
if l.is_test and (l.id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
or not exists(select 1 from mission_generic_owner.simulation_sources where carrier_mission_id=m.mission_id)
or combat_consumer_private.staff_test_allowed(l.id,array_append(coalesce(us,'{}'::uuid[]),auth.uid()),false) is distinct from true)
then raise exception 'MC_HUMAN_TEST_SCOPE' using errcode='42501';end if;
end $function$

