CREATE OR REPLACE FUNCTION mission_factory_owner.c395_active_human_assert_v1(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;users uuid[];
BEGIN
PERFORM mission_factory_owner.c395_source_assert_v1(p_session);
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR SHARE;
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
SELECT array_agg(c.user_id ORDER BY c.id) INTO users FROM unnest(q.roster_character_ids) x(id) JOIN public.characters c ON c.id=x.id;
IF q.state IS DISTINCT FROM 'started' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR m.stato NOT IN('in_corso','chiusura')
OR m.master_user IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated'
OR q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation'
OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true
THEN RAISE EXCEPTION 'C395_HUMAN_ACTIVE_STAFF_SCOPE_REQUIRED' USING ERRCODE='42501';END IF;
END $function$

