CREATE OR REPLACE FUNCTION mission_factory_owner.c444_source_read_assert_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q mission_factory_owner.quest_run_sources%rowtype;
m public.master_v2_sessions%rowtype;
e mission_factory_owner.quest_episodes%rowtype;
a mission_factory_owner.quest_arcs%rowtype;
pub mission_factory_owner.publications%rowtype;
p public.mission_plans%rowtype;
v public.mission_plan_versions%rowtype;
d mission_generic_owner.definitions%rowtype;
b mission_generic_owner.run_bindings%rowtype;
loc public.locations%rowtype;
users uuid[];
begin

PERFORM mission_factory_owner.c444_read_identity_v1(p_session);
PERFORM mission_factory_owner.c412_revision_provenance_v1(p_session);
select * into strict q from mission_factory_owner.quest_run_sources where session_id=p_session for share;
select * into strict m from public.master_v2_sessions where id=p_session for share;
select * into strict e from mission_factory_owner.quest_episodes where id=q.episode_id for share;
select * into strict a from mission_factory_owner.quest_arcs where id=q.arc_id for share;
select * into strict pub from mission_factory_owner.publications
where request_key=a.publication_request for share;
select * into strict p from public.mission_plans where id=q.plan_id for share;
select * into strict v from public.mission_plan_versions where id=q.plan_version_id for share;
select * into strict d from mission_generic_owner.definitions where id=q.definition_id for share;
select * into strict b from mission_generic_owner.run_bindings where master_session_id=p_session for share;
select * into strict loc from public.locations where id=q.location_id for share;
select array_agg(c.user_id order by x.ord) into users
from unnest(q.roster_character_ids) with ordinality x(id,ord)
join public.characters c on c.id=x.id and c.user_id is not null;
